import React, { useState } from "react";
import { predict } from "./api";
import Result from "./Result";

export default function PredictForm() {
  const [formData, setFormData] = useState({
    industry_enc: "",
    country_enc: "",
    company_age: "",
    avg_size: "",
    current_employee_estimate: "",
    total_employee_estimate: "",
    model_type: "rf_category"
  });

  const [result, setResult] = useState(null);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState(null);

  const handleChange = (e) => {
    const { name, value } = e.target;
    setFormData((prev) => ({
      ...prev,
      [name]: value
    }));
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    setLoading(true);
    setError(null);
    setResult(null);

    try {
      const payload = {
        ...formData,
        industry_enc: Number(formData.industry_enc),
        country_enc: Number(formData.country_enc),
        company_age: Number(formData.company_age),
        avg_size: Number(formData.avg_size),
        current_employee_estimate: Number(formData.current_employee_estimate),
        total_employee_estimate: Number(formData.total_employee_estimate)
      };

      const res = await predict(payload);
      setResult(res);
    } catch (err) {
      console.error("Prediction error:", err);
      setError("Failed to get prediction. Check backend connection.");
    }

    setLoading(false);
  };

  return (
    <div>
      <form onSubmit={handleSubmit} style={styles.form}>
        {renderInput("Industry (encoded)", "industry_enc")}
        {renderInput("Country (encoded)", "country_enc")}
        {renderInput("Company Age", "company_age")}
        {renderInput("Average Size", "avg_size")}
        {renderInput("Current Employee Estimate", "current_employee_estimate")}
        {renderInput("Total Employee Estimate", "total_employee_estimate")}

        <div style={styles.field}>
          <label>Model Type:</label>
          <select
            name="model_type"
            value={formData.model_type}
            onChange={handleChange}
            style={styles.input}
          >
            <option value="rf_category">RF Category</option>
            <option value="rf_level">RF Level</option>
            <option value="xgb_category">XGB Category</option>
            <option value="xgb_level">XGB Level</option>
          </select>
        </div>

        <button type="submit" disabled={loading} style={styles.button}>
          {loading ? "Predicting..." : "Predict"}
        </button>
      </form>

      {error && <p style={styles.error}>{error}</p>}

      {result && <Result result={result} />}
    </div>
  );
}

function renderInput(label, name) {
  return (
    <div style={styles.field}>
      <label>{label}:</label>
      <input
        type="number"
        name={name}
        required
        style={styles.input}
      />
    </div>
  );
}

const styles = {
  form: {
    display: "flex",
    flexDirection: "column",
    gap: "15px"
  },
  field: {
    display: "flex",
    flexDirection: "column"
  },
  input: {
    padding: "8px",
    borderRadius: "6px",
    border: "1px solid #ccc",
    marginTop: "5px"
  },
  button: {
    padding: "10px",
    borderRadius: "6px",
    border: "none",
    backgroundColor: "#2c3e50",
    color: "#fff",
    cursor: "pointer"
  },
  error: {
    color: "red",
    marginTop: "15px"
  }
};
